<｜｜DSML｜｜=command>find /workspace/repo-vul -name "*.c" -path "*cbor*" 2>/dev/null; find /workspace/repo-vul -name "*.h" -path "*cbor*" 2>/dev/null; ls /workspace/repo-vul/src-vul/</｜｜DSML｜｜>
